SELECT 'INSERT INTO dbo.bs_asm_bom (单据编号,产品编码,产品名称,规格型号,工序,版本号,默认BOM,工艺路线名称,来源,状态,行序,子件编码,子件名称,子件规格,计量单位,标准用量,用量分子,用量分母,损耗量,行备注,asp_user1,asp_time1,asp_user2,asp_time2,asp_cancel,备注) VALUES (' + char(39)+REPLACE(单据编号,'''','''''')+char(39)+','+char(39)+REPLACE(产品编码,'''','''''')+char(39)+',' + ISNULL(char(39)+REPLACE(产品名称,'''','''''')+char(39),'NULL') + ',' + ISNULL(char(39)+REPLACE(规格型号,'''','''''')+char(39),'NULL') + ',' + char(39)+REPLACE(工序,'''','''''')+char(39)+',' + ISNULL(char(39)+REPLACE(版本号,'''','''''')+char(39),'NULL') + ',' + ISNULL(char(39)+REPLACE(默认BOM,'''','''''')+char(39),'NULL') + ',' + ISNULL(char(39)+REPLACE(工艺路线名称,'''','''''')+char(39),'NULL') + ',' + ISNULL(char(39)+REPLACE(来源,'''','''''')+char(39),'NULL') + ',' + ISNULL(char(39)+REPLACE(状态,'''','''''')+char(39),'NULL') + ',' + CAST(行序 AS varchar) + ',' + char(39)+REPLACE(子件编码,'''','''''')+char(39)+',' + ISNULL(char(39)+REPLACE(子件名称,'''','''''')+char(39),'NULL') + ',' + ISNULL(char(39)+REPLACE(子件规格,'''','''''')+char(39),'NULL') + ',' + ISNULL(char(39)+REPLACE(计量单位,'''','''''')+char(39),'NULL') + ',' + CAST(标准用量 AS varchar) + ',' + CAST(用量分子 AS varchar) + ',' + CAST(用量分母 AS varchar) + ',' + CAST(损耗量 AS varchar) + ',' + ISNULL(char(39)+REPLACE(行备注,'''','''''')+char(39),'NULL') + ',' + ISNULL(char(39)+REPLACE(asp_user1,'''','''''')+char(39),'NULL') + ',' + ISNULL(char(39)+CONVERT(varchar,asp_time1,126)+char(39),'NULL') + ',' + ISNULL(char(39)+REPLACE(asp_user2,'''','''''')+char(39),'NULL') + ',' + ISNULL(char(39)+CONVERT(varchar,asp_time2,126)+char(39),'NULL') + ',' + char(39)+REPLACE(asp_cancel,'''','''''')+char(39)+',' + ISNULL(char(39)+REPLACE(备注,'''','''''')+char(39),'NULL') + ');' AS stmt FROM bs_asm_bom WHERE 单据编号='C-23-11_V0001' ORDER BY 行序
